// scripts/schema-reference.js — Writes SCHEMA_REFERENCE.sql: the full schema the app runs on
// (db/schema.sql baseline + every db/migrations step), exported from an in-process Postgres.
// Usage: npm run schema:reference   (offline; no DATABASE_URL needed)
"use strict";

const fs = require("fs");
const path = require("path");
const { createTestDb } = require("../tests/harness/db");
const { exportSchema } = require("./export-schema");

const OUT = path.join(__dirname, "..", "SCHEMA_REFERENCE.sql");
const HEADER = [
  "-- SCHEMA_REFERENCE.sql — the schema after every migration (generated by scripts/schema-reference.js; do not edit by hand)",
  "-- = db/schema.sql (baseline exported from the live database) + db/migrations/* applied in order.",
  "-- Regenerate with `npm run schema:reference` whenever a migration is added; a test fails when it is stale.",
  ""
].join("\n");

/** The reference text (deterministic: no timestamps). */
async function buildReference() {
  const { pool } = await createTestDb();
  try {
    const ddl = await exportSchema(pool);
    // Drop the export header (it carries a timestamp and names db/schema.sql).
    const body = ddl.split("\n").slice(3).join("\n");
    return `${HEADER}\n${body}`;
  } finally {
    await pool.end();
  }
}

if (require.main === module) {
  buildReference()
    .then((text) => {
      fs.writeFileSync(OUT, text);
      console.log(`Wrote ${OUT} (${text.split("\n").length} lines)`);
    })
    .catch((err) => {
      console.error("Schema reference failed:", err.message);
      process.exit(1);
    });
}

module.exports = { buildReference, OUT };
